//! owen.json configuration — the single source of truth for the redirecter,
//! generated by the Owen Web Console (Redirecter tab) or written by hand.

use serde::{Deserialize, Serialize};

pub const DEFAULT_DOMAINS: &[&str] = &[
    "game-social.epicgames.com",
    "ol.epicgames.com",
    "ol.epicgames.net",
    "on.epicgames.com",
    "ak.epicgames.com",
    "epicgames.dev",
];

/// The patchable default backend URL, laid out exactly like the original C
/// engine's `static char g_backend_url[4096]`: the URL, a NUL terminator and
/// zero padding. The launcher's `NativeBuilder` binary-patches this buffer in
/// the packaged .so (it searches for `http://127.0.0.1:3551\0` and rewrites
/// in place), so the runtime default MUST be read from here — never from a
/// Rust string literal (literals are packed without NULs and would corrupt
/// neighbouring rodata when patched).
#[used]
pub static DEFAULT_BACKEND_URL: [u8; 4096] = {
    const URL: &[u8] = b"http://127.0.0.1:3551";
    let mut buf = [0u8; 4096];
    let mut i = 0;
    while i < URL.len() {
        buf[i] = URL[i];
        i += 1;
    }
    buf
};

/// Read the (possibly NativeBuilder-patched) default backend URL.
pub fn default_base_url() -> String {
    let len = DEFAULT_BACKEND_URL
        .iter()
        .position(|&b| b == 0)
        .unwrap_or(0);
    String::from_utf8_lossy(&DEFAULT_BACKEND_URL[..len]).into_owned()
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ServerConfig {
    /// Backend base URL, scheme kept VERBATIM — `http://` and `https://`
    /// are both first-class. Never rewritten, never auto-prepended.
    pub base_url: String,
    pub xmpp_host: String,
    pub xmpp_port: u16,
    pub login_path: String,
    pub graphql_path: String,
}

impl Default for ServerConfig {
    fn default() -> Self {
        ServerConfig {
            base_url: default_base_url(),
            xmpp_host: "127.0.0.1".into(),
            xmpp_port: 5222,
            login_path: "/login".into(),
            graphql_path: "/partyhub/graphql".into(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ExtraRule {
    /// Either a host suffix (`example.com`) or a path prefix (`/launcher/api`).
    pub r#match: String,
    /// Path that replaces the matched URL's path (query is preserved).
    pub replace_path: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct RedirectConfig {
    #[serde(default = "default_domains")]
    pub domains: Vec<String>,
    #[serde(default)]
    pub extra_rules: Vec<ExtraRule>,
}

fn default_domains() -> Vec<String> {
    DEFAULT_DOMAINS.iter().map(|s| s.to_string()).collect()
}

impl Default for RedirectConfig {
    fn default() -> Self {
        RedirectConfig {
            domains: default_domains(),
            extra_rules: Vec::new(),
        }
    }
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Default)]
pub struct ManifestConfig {
    /// `auto` rewrites manifest/asset CDN traffic to the backend, `off` leaves
    /// it untouched.
    pub mode: ManifestMode,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Default)]
#[serde(rename_all = "lowercase")]
pub enum ManifestMode {
    #[default]
    Auto,
    Off,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct WebviewConfig {
    /// Empty = derive from `server.base_url + server.login_path`.
    #[serde(default)]
    pub login_url: String,
    /// Unlock NetworkSecurityPolicy so plain-HTTP login pages work.
    #[serde(default = "default_true")]
    pub force_cleartext: bool,
    /// `auto` installs the Kairos/WebView ART hooks, `off` disables them.
    pub partyhub: PartyHubMode,
}

fn default_true() -> bool {
    true
}

impl Default for WebviewConfig {
    fn default() -> Self {
        WebviewConfig {
            login_url: String::new(),
            force_cleartext: true,
            partyhub: PartyHubMode::Auto,
        }
    }
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Default)]
pub enum PartyHubMode {
    #[default]
    Auto,
    Off,
}

/// Console-window toggles — the runtime (ART-hook) replacement for the legacy
/// smali `GameActivity.dispatchTouchEvent` + `forceShowConsoleWindow_test`
/// patch that `SmaliPatcher.patchGameActivityConsole` used to bake into
/// `classes.dex` at patch time (season-aware four-finger-touch console).
///
/// The patcher no longer edits dex: it writes `console.enabled` into the
/// `owen.json` next to the patched APK (see `owen_patcher::patch_plan`),
/// and libowen.so applies the touch hook at runtime.
///
/// Kotlin source map: `SmaliPatcher.appendConsolePatch` → `ConsoleConfig`.
/// Source: Owen-Launcher app/src/main/kotlin/com/abdallhrgx/owenlauncher/core/apk/SmaliPatcher.kt
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Default)]
pub struct ConsoleConfig {
    /// `true` = enable the four-finger-touch console hook at runtime
    /// (`false` keeps the game's default behaviour — matches a dev build
    /// that already ships a console, i.e. `isDev == true`).
    #[serde(default)]
    pub enabled: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct DetectConfig {
    /// `auto` = dlsym first, signature scan fallback; the other values pin
    /// one strategy.
    pub strategy: DetectStrategy,
    pub min_score: u32,
}

impl Default for DetectConfig {
    fn default() -> Self {
        DetectConfig {
            strategy: DetectStrategy::Auto,
            min_score: 6,
        }
    }
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Default)]
#[serde(rename_all = "kebab-case")]
pub enum DetectStrategy {
    #[default]
    Auto,
    SymbolsOnly,
    SignatureOnly,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct HookToggles {
    pub curl: bool,
    pub art_webview: bool,
}

impl Default for HookToggles {
    fn default() -> Self {
        HookToggles {
            curl: true,
            art_webview: true,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct OwenConfig {
    pub version: u32,
    #[serde(default)]
    pub server: ServerConfig,
    #[serde(default)]
    pub redirect: RedirectConfig,
    #[serde(default)]
    pub manifest: ManifestConfig,
    #[serde(default)]
    pub webview: WebviewConfig,
    /// Console-window hook switch (the zero-smali replacement for the legacy
    /// GameActivity console patch) — see [`ConsoleConfig`].
    #[serde(default)]
    pub console: ConsoleConfig,
    #[serde(default)]
    pub detect: DetectConfig,
    #[serde(default)]
    pub hooks: HookToggles,
}

impl Default for OwenConfig {
    fn default() -> Self {
        OwenConfig {
            version: 1,
            server: ServerConfig::default(),
            redirect: RedirectConfig::default(),
            manifest: ManifestConfig::default(),
            webview: WebviewConfig::default(),
            console: ConsoleConfig::default(),
            detect: DetectConfig::default(),
            hooks: HookToggles::default(),
        }
    }
}

impl OwenConfig {
    /// Fully-derived login URL (explicit override or base + path).
    pub fn login_url(&self) -> String {
        if !self.webview.login_url.is_empty() {
            self.webview.login_url.clone()
        } else {
            format!("{}{}", self.server.base_url, self.server.login_path)
        }
    }

    /// Fully-derived partyhub graphql URL.
    pub fn graphql_url(&self) -> String {
        format!("{}{}", self.server.base_url, self.server.graphql_path)
    }

    /// Load the configuration, trying the standard on-device locations.
    pub fn load() -> OwenConfig {
        for path in Self::candidate_paths() {
            if let Ok(text) = std::fs::read_to_string(&path) {
                match serde_json::from_str::<OwenConfig>(&text) {
                    Ok(cfg) => {
                        owen_log::info(&format!("owen: config loaded from {path}"));
                        return cfg;
                    }
                    Err(e) => {
                        owen_log::warn(&format!("owen: bad config at {path}: {e}"));
                    }
                }
            }
        }
        owen_log::info("owen: no config found — using the default backend URL");
        OwenConfig::default()
    }

    fn candidate_paths() -> Vec<String> {
        let mut paths = Vec::new();
        if let Ok(env) = std::env::var("OWEN_CONFIG") {
            paths.push(env);
        }
        // Per-package external dir: /sdcard/Android/data/<pkg>/files/owen.json
        if let Ok(cmdline) = std::fs::read_to_string("/proc/self/cmdline") {
            let pkg = cmdline.split('\0').next().unwrap_or("").trim();
            if !pkg.is_empty() {
                paths.push(format!("/sdcard/Android/data/{pkg}/files/owen.json"));
            }
        }
        paths.push("/data/local/tmp/owen.json".to_string());
        paths.push("/sdcard/owen.json".to_string());
        paths
    }
}

/// Logging shim (logcat + stderr), available to every module.
pub mod owen_log {
    #[cfg(target_os = "android")]
    extern "C" {
        fn __android_log_print(prio: i32, tag: *const u8, fmt: *const u8, ...) -> i32;
    }

    #[cfg(target_os = "android")]
    fn log(prio: i32, msg: &str) {
        let tag = b"Owen\0";
        // logcat needs a literal format string; pass "%s" + one argument.
        let fmt = b"%s\0";
        let c = std::ffi::CString::new(msg.replace('\0', " ")).unwrap_or_default();
        // SAFETY: __android_log_print with "%s" and a valid C string is the
        // documented usage.
        unsafe {
            __android_log_print(prio, tag.as_ptr(), fmt.as_ptr(), c.as_ptr());
        }
    }

    #[cfg(not(target_os = "android"))]
    fn log(prio: i32, msg: &str) {
        let tag = if prio <= 3 {
            "E"
        } else if prio == 4 {
            "W"
        } else {
            "I"
        };
        eprintln!("[{tag}/Owen] {msg}");
    }

    pub fn info(msg: &str) {
        log(4 - 1, msg);
    }
    pub fn warn(msg: &str) {
        log(4, msg);
    }
    pub fn error(msg: &str) {
        log(5, msg);
    }
}
